from pathlib import Path
import base64
import gzip
import hashlib

PAYLOAD = """"""
EXPECTED_SHA256 = "5e7a7973d897b0b977db39eac3fac5ccf08ae9ba3852569e7f47bb5bb5f7186a"
TARGET = Path("supabase/migrations/20260817170000_reconciliar_proveniencia_perfis_wvetro_v1.sql")

data = gzip.decompress(base64.b64decode(PAYLOAD))
actual = hashlib.sha256(data).hexdigest()
if actual != EXPECTED_SHA256:
    raise SystemExit(f"hash incorreto: {actual}")
TARGET.write_bytes(data)
print(f"migration reconstruída: {len(data)} bytes sha256={actual}")
